    @Test
    @DisplayName("译文批准：作者不能审核自己的译文 422；译文版本不匹配 422；成功批准")
    void approveTranslation() throws Exception {
        long docId = createDocument(newRequestId(), "[\"en\"]",
                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
