```java
/** 法律审签状态：终态 APPROVED / REJECTED。 */
private static final String LEGAL_APPROVED = "APPROVED";
private static final String LEGAL_REJECTED = "REJECTED";

@Transactional
public ApiDtos.LegalSignResponse submitLegalSign(long documentId, String segmentId, String language,
                                                 String actorId, ApiDtos.LegalSignRequest request) {
    lockDocument(documentId);
    String normalizedLanguage = normalizeLanguage(language);
    SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
    TranslationRow translation = repository.findTranslation(documentId, segmentId, normalizedLanguage)
            .orElseThrow(() -> ApiException.notFound("译文不存在: " + segmentId + "/" + normalizedLanguage));
    if (translation.translationVersion() != request.expectedVersion()) {
        throw ApiException.conflict("译文版本冲突：当前译文版本 " + translation.translationVersion()
                + "，与期望的 " + request.expectedVersion() + " 不一致");
    }
    ApprovalRow approval = repository.findApproval(documentId, segmentId, normalizedLanguage).orElse(null);
    if (approval == null || approval.translationVersion() != translation.translationVersion()
            || approval.sourceVersion() != segment.sourceVersion()) {
        throw ApiException.unprocessable("译文未获有效批准，不能提交法律审签: " + segmentId + "/" + normalizedLanguage);
    }
    String reason = request.reason() == null ? "" : request.reason();
    if (LEGAL_REJECTED.equals(request.status()) && reason.isBlank()) {
        throw ApiException.unprocessable("拒绝说明不能为空");
    }
    repository.upsertLegalSign(documentId, new LegalSignRow(segmentId, normalizedLanguage,
            translation.translationVersion(), actorId, request.status(), reason));
    return new ApiDtos.LegalSignResponse(documentId, segmentId, normalizedLanguage, actorId,
            translation.translationVersion(), request.status(), reason);
}
```

