```java
private List<ApiDtos.PublishBlocker> computeLegalBlockers(DocumentRow document) {
    List<SegmentRow> segments = repository.listSegments(document.documentId());
    Map<String, TranslationRow> translations = ...;
    Map<String, LegalSignRow> legalSigns = ...;
    List<ApiDtos.PublishBlocker> blockers = new ArrayList<>();
    for (SegmentRow segment : segments) {
        for (String language : document.targetLanguages()) {
            TranslationRow translation = translations.get(key(segment.segmentId(), language));
            if (translation == null) continue; // 缺译由发布主流程报告
            LegalSignRow sign = legalSigns.get(key(segment.segmentId(), language, translation.translationVersion()));
            if (sign == null) {
                blockers.add(new ApiDtos.PublishBlocker(segment.segmentId(), language,
                        translation.translationVersion(), "MISSING", "缺少法律审签"));
            } else if (LEGAL_REJECTED.equals(sign.status())) {
                blockers.add(new ApiDtos.PublishBlocker(segment.segmentId(), language,
                        translation.translationVersion(), "REJECTED", sign.reason()));
            }
        }
    }
    return blockers;
}
```

