 */
protected int prepareFullySigned(long documentId, List<String> segments, List<String> languages,
                                 String author, String reviewer, String legalReviewer,
                                 String contentPrefix) throws Exception {
    int draftVersion = 1;
    for (String segmentId : segments) {
        for (String language : languages) {
            assertThat(submitTranslation(documentId, segmentId, language, author,
                    contentPrefix + "-" + segmentId + "-" + language, 1, newRequestId()).status())
                    .isEqualTo(200);
            draftVersion++;
            assertThat(approve(documentId, segmentId, language, reviewer, 1, newRequestId()).status())
                    .isEqualTo(200);
            assertThat(legalSign(documentId, segmentId, language, legalReviewer, 1,
                    "APPROVED", "合规", newRequestId()).status()).isEqualTo(200);
            draftVersion++;
        }
    }
    return draftVersion;
}

